CREATE DATABASE IF NOT EXISTS homeease CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE homeease;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,phone VARCHAR(30),address TEXT,role ENUM('customer','admin') NOT NULL DEFAULT 'customer',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS services(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE,description VARCHAR(255),base_price DECIMAL(10,2) NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS providers(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,phone VARCHAR(30),skills VARCHAR(255) NOT NULL,location VARCHAR(120),experience_years INT NOT NULL DEFAULT 0,rating DECIMAL(2,1) NOT NULL DEFAULT 4.5,available BOOLEAN NOT NULL DEFAULT TRUE,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS bookings(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,service_id INT NOT NULL,provider_id INT NULL,description TEXT NOT NULL,service_date DATE NOT NULL,time_slot VARCHAR(40) NOT NULL,urgent BOOLEAN NOT NULL DEFAULT FALSE,estimated_cost DECIMAL(10,2) NOT NULL,status ENUM('Requested','Confirmed','Provider on the Way','In Progress','Completed','Cancelled') NOT NULL DEFAULT 'Requested',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(service_id) REFERENCES services(id),FOREIGN KEY(provider_id) REFERENCES providers(id),INDEX idx_queue(urgent,status,created_at));
CREATE TABLE IF NOT EXISTS payments(id INT AUTO_INCREMENT PRIMARY KEY,booking_id INT NOT NULL UNIQUE,amount DECIMAL(10,2) NOT NULL,method VARCHAR(40) NOT NULL DEFAULT 'Demo',status ENUM('Pending','Paid','Failed','Refunded') NOT NULL DEFAULT 'Pending',transaction_ref VARCHAR(100),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(booking_id) REFERENCES bookings(id));
CREATE TABLE IF NOT EXISTS service_reports(id INT AUTO_INCREMENT PRIMARY KEY,booking_id INT NOT NULL UNIQUE,work_details TEXT NOT NULL,materials_used TEXT,final_cost DECIMAL(10,2) NOT NULL,service_date DATE NOT NULL DEFAULT (CURRENT_DATE),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(booking_id) REFERENCES bookings(id));
CREATE TABLE IF NOT EXISTS warranties(id INT AUTO_INCREMENT PRIMARY KEY,report_id INT NOT NULL UNIQUE,duration_months INT NOT NULL DEFAULT 0,expiry_date DATE,terms TEXT,FOREIGN KEY(report_id) REFERENCES service_reports(id));
CREATE TABLE IF NOT EXISTS complaints(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,booking_id INT NULL,subject VARCHAR(150) NOT NULL,details TEXT NOT NULL,status ENUM('Open','In Review','Resolved') NOT NULL DEFAULT 'Open',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(booking_id) REFERENCES bookings(id));
